protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9: default discriminator property renamed from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents and direct SQL queries
        // referencing c.Discriminator remain compatible.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9: id no longer includes the discriminator (was "Product|123", now "123").
        // Preserve the old compound format so existing documents remain accessible.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // HasIndex removed — EF Core 9 Cosmos provider now throws at startup.
    // Cosmos DB indexing is managed via the container's indexing policy
    // (Azure Portal / Bicep / Terraform), not through EF Core.
}

